// Emulates Vue 3's reactive() skip check (packages/reactivity/src/reactive.ts):
// an object is left un-proxied when its `__v_skip` marker is truthy.
const ReactiveFlags = { SKIP: '__v_skip' };
function vueReactive(target) {
  if (target[ReactiveFlags.SKIP]) return target;   // markRaw / __v_skip opt-out
  return new Proxy(target, {});                     // otherwise Vue proxies it
}
module.exports = { vueReactive };
EOF
