     * If eable select by brushing
     */
    brushSelect?: boolean

    brushStyle?: ItemStyleOption

    emphasis?: {
        handleLabel: SliderHandleLabelOption
        handleStyle?: ItemStyleOption
        moveHandleStyle?: ItemStyleOption
    },

